        intervals.sort(key=lambda x: x[0])
        result = []
        for ts, te, m in queries:
            cnt = 0
            for t, n, interval_m, s in intervals:
                if t < ts:
                    continue
                if t >= te:
                    break
                if interval_m == m and s == 1:
                    cnt += 1
            result.append(cnt)
        return result 

